<?php declare(strict_types=1); use App\Core\Csrf; $money=static fn($c):string=>'R$ '.number_format(((int)$c)/100,2,',','.'); ob_start(); ?><section class="account-hero"><div><p class="eyebrow">Financeiro</p><h2>Pagamentos</h2><p>Registros confirmados e estados do provedor.</p></div></section><?php if(is_string($message??null)&&$message!==''): ?><p class="account-card" role="status"><?= e($message) ?></p><?php endif; ?><section class="panel"><table><thead><tr><th>Data</th><th>Plano</th><th>Status</th><th>Valor</th></tr></thead><tbody><?php foreach($payments as $payment): ?><tr><td><?= e((string)($payment['paid_at']??'—')) ?></td><td><?= (int)$payment['plan_id'] ?></td><td><?= e((string)$payment['status']) ?></td><td><?= e($money($payment['paid_amount_cents']??0)) ?></td></tr><?php endforeach; ?><?php if($payments===[]): ?><tr><td colspan="4">Nenhum pagamento registrado.</td></tr><?php endif; ?></tbody></table></section><section class="panel"><h2>Assinaturas</h2><?php foreach($subscriptions as $subscription): ?><div><strong><?= e((string)$subscription['status']) ?></strong><?php if(($subscription['provider']??'')==='pagarme'): ?><p class="plan-note">O Pagar.me só permite <strong>cancelamento imediato</strong>. Esta ação não agenda o fim do período.</p><form method="post" action="/conta/assinaturas/<?= (int)$subscription['id'] ?>/cancelar"><input type="hidden" name="_token" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="immediate" value="1"><label><input required type="checkbox" name="confirm_immediate" value="1"> Confirmo o cancelamento imediato.</label><button type="submit">Cancelar agora</button></form><?php else: ?><form method="post" action="/conta/assinaturas/<?= (int)$subscription['id'] ?>/cancelar"><input type="hidden" name="_token" value="<?= e(Csrf::token()) ?>"><button type="submit">Cancelar ao fim do período</button></form><?php endif; ?><form method="post" action="/checkout/<?= e((string)$subscription['checkout_attempt_id']) ?>/reconciliar"><input type="hidden" name="_token" value="<?= e(Csrf::token()) ?>"><button type="submit">Reconciliar status</button></form></div><?php endforeach; ?></section><?php $content=(string)ob_get_clean(); require __DIR__.'/../layouts/app.php';
